#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    std::vector<int> data{8, 3, 5, 1};
    std::sort(data.begin(), data.end());
    const auto it = std::find(data.begin(), data.end(), 5);
    std::cout << data.front() << ", index=" << std::distance(data.begin(), it) << '\n';
}
